<body>
  <main class="card">
    <h1>Contact Support</h1>
    <p class="subtitle">Send us your details and we&apos;ll get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input
          id="full-name"
          name="fullName"
          type="text"
          autocomplete="name"
          required
          aria-describedby="full-name-error"
        />
        <div class="error" id="full-name-error" aria-live="polite"></div>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input
          id="email-address"
          name="emailAddress"
          type="text"
          autocomplete="email"
          inputmode="email"
          required
          aria-describedby="email-address-error"
        />
        <div class="error" id="email-address-error" aria-live="polite"></div>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input
          id="phone-number"
          name="phoneNumber"
          type="text"
          autocomplete="tel"
          inputmode="tel"
          aria-describedby="phone-number-helper phone-number-error"
          placeholder="555-123-4567"
        />
        <div class="helper" id="phone-number-helper">Optional. Use the format 555-123-4567.</div>
        <div class="error" id="phone-number-error" aria-live="polite"></div>
      </div>

      <div class="actions">
        <button type="submit">Submit</button>
        <div class="status" id="form-status" aria-live="polite"></div>
      </div>
    </form>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const fields = {
      fullName: {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate(value) {
          if (!value.trim()) {
            return 'Full name is required.';
          }
          return '';
        }
      },
      emailAddress: {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return 'Email address is required.';
          }
          const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailPattern.test(trimmed)) {
            return 'Enter a valid email address.';
          }
          return '';
        }
      },
      phoneNumber: {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return '';
          }
          const phonePattern = /^\d{3}-\d{3}-\d{4}$/;
          if (!phonePattern.test(trimmed)) {
            return 'Use the format 555-123-4567.';
          }
          return '';
        }
      }
    };

    const status = document.getElementById('form-status');

    function setFieldState(field, message) {
      field.error.textContent = message;
      field.input.setAttribute('aria-invalid', message ? 'true' : 'false');
    }

    function validateField(name) {
      const field = fields[name];
      const message = field.validate(field.input.value);
      setFieldState(field, message);
      return !message;
    }

    Object.keys(fields).forEach((name) => {
      const field = fields[name];
      field.input.addEventListener('blur', () => validateField(name));
      field.input.addEventListener('input', () => {
        if (field.error.textContent) {
          validateField(name);
        }
        status.textContent = '';
      });
    });

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      const order = ['fullName', 'emailAddress', 'phoneNumber'];
      const firstInvalid = order.find((name) => !validateField(name));

      if (firstInvalid) {
        fields[firstInvalid].input.focus();
        status.textContent = '';
        return;
      }

      status.textContent = 'Form ready to submit.';
      form.reset();
      Object.keys(fields).forEach((name) => setFieldState(fields[name], ''));
    });
  </script>
