      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input
          id="email-address"
          name="emailAddress"
          type="text"
          autocomplete="email"
          inputmode="email"
          required
          aria-describedby="email-address-error"
        />
        <div class="error" id="email-address-error" aria-live="polite"></div>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input
          id="phone-number"
          name="phoneNumber"
          type="text"
          autocomplete="tel"
          inputmode="tel"
          aria-describedby="phone-number-helper phone-number-error"
          placeholder="555-123-4567"
        />
        <div class="helper" id="phone-number-helper">Optional. Use the format 555-123-4567.</div>
        <div class="error" id="phone-number-error" aria-live="polite"></div>
      </div>

      <div class="actions">
        <button type="submit">Submit</button>
        <div class="status" id="form-status" aria-live="polite"></div>
      </div>
